// Formats the alert Laravel sent. Every number comes from the engine payload;
// this node never computes a new one.
const p = $('Margin alert webhook').first().json.body;

const fmt = (value, unit) => unit === 'EUR'
  ? '€' + Math.round(value).toLocaleString('en-US')
  : Math.round(value * 100) + '%';

const observed = fmt(p.observed, p.unit);
const threshold = fmt(p.threshold, p.unit);
const company = p.company?.name ?? 'your business';
const sim = p.simulation
  ? `Forecast from ${p.simulation.paths.toLocaleString('en-US')} simulated futures (scenario: ${p.simulation.scenario}, seed ${p.simulation.seed}). Shown as a forecast, not a certainty.`
  : 'Forecast from the latest engine run.';
const link = p.dashboard_url
  ? `<p style="margin:24px 0"><a href="${p.dashboard_url}" style="background:#0f766e;color:#fff;padding:12px 20px;border-radius:8px;text-decoration:none;font-weight:600">Open Margin Shield and see the actions</a></p>`
  : '';

const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;max-width:560px;margin:auto;color:#1f2937">
  <div style="background:#0f172a;color:#fff;padding:16px 24px;border-radius:12px 12px 0 0">
    <strong>Margin Shield</strong> · alert for ${company}
  </div>
  <div style="border:1px solid #e5e7eb;border-top:0;padding:24px;border-radius:0 0 12px 12px">
    <p style="margin:0 0 8px;color:#6b7280">${p.metric_name}</p>
    <p style="margin:0;font-size:36px;font-weight:700;color:#b91c1c">${observed}</p>
    <p style="margin:4px 0 20px">Your limit is <strong>${threshold}</strong>. This value is now above it.</p>
    <table style="width:100%;border-collapse:collapse;font-size:14px">
      <tr><td style="padding:6px 0;color:#6b7280">Label</td><td style="padding:6px 0"><span style="background:#fef3c7;padding:2px 8px;border-radius:999px">${p.label}</span></td></tr>
      <tr><td style="padding:6px 0;color:#6b7280">Basis</td><td style="padding:6px 0">${sim}</td></tr>
      <tr><td style="padding:6px 0;color:#6b7280">Checked</td><td style="padding:6px 0">${new Date(p.triggered_at).toLocaleString('en-GB', { timeZone: 'Europe/Belgrade' })}</td></tr>
    </table>
    ${link}
    <p style="font-size:12px;color:#9ca3af;margin-top:24px">You get this email because you set this limit. You get at most one email per limit every 7 days.</p>
  </div>
</div>`;

return [{ json: {
  to: p.recipient_email,
  subject: `⚠ ${company}: ${p.metric_name} is ${observed} (your limit: ${threshold})`,
  html,
} }];
